#!/usr/bin/env python3
"""Drive the live neuvector-mcp server over streamable-http.

The transport answers with SSE, so every JSON-RPC reply has to be pulled out of
the `data:` lines. Bearer token is read from bearer.txt and never printed.
"""

from __future__ import annotations

import json
import os
import ssl
import sys
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
URL = os.environ.get("MCP_URL", "http://192.168.7.166:8080/mcp")
TOKEN = open(os.path.join(HERE, "bearer.txt")).read().strip()

CTX = ssl.create_default_context()
CTX.check_hostname = False
CTX.verify_mode = ssl.CERT_NONE

_session: str | None = None
_id = 0


def rpc(method: str, params: dict | None = None, notify: bool = False):
    global _session, _id
    body: dict = {"jsonrpc": "2.0", "method": method}
    if params is not None:
        body["params"] = params
    if not notify:
        _id += 1
        body["id"] = _id

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
        "Authorization": f"Bearer {TOKEN}",
    }
    if _session:
        headers["mcp-session-id"] = _session

    req = urllib.request.Request(URL, data=json.dumps(body).encode(), headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=120, context=CTX) as r:
        sid = r.headers.get("mcp-session-id")
        if sid:
            _session = sid
        raw = r.read().decode()

    if notify:
        return None
    for line in raw.splitlines():
        if line.startswith("data:"):
            return json.loads(line[5:].strip())
    return json.loads(raw) if raw.strip() else None


def call_tool(name: str, args: dict) -> dict:
    res = rpc("tools/call", {"name": name, "arguments": args})
    if "error" in res:
        return {"_rpc_error": res["error"]}
    content = res["result"].get("content", [])
    for c in content:
        if c.get("type") == "text":
            try:
                return json.loads(c["text"])
            except json.JSONDecodeError:
                return {"_text": c["text"]}
    return res["result"]


def main() -> int:
    init = rpc("initialize", {
        "protocolVersion": "2025-06-18",
        "capabilities": {},
        "clientInfo": {"name": "session-probe", "version": "0"},
    })
    info = init["result"]["serverInfo"]
    print(f"initialize: {info.get('name')} {info.get('version')}  session={'yes' if _session else 'no'}")
    rpc("notifications/initialized", {}, notify=True)

    tools = rpc("tools/list")["result"]["tools"]
    names = sorted(t["name"] for t in tools)
    print(f"tools/list: {len(names)} tools exposed")

    for step in sys.argv[1:]:
        if step == "list-registries":
            print("\n--- nv_list_registries ---")
            out = call_tool("nv_list_registries", {})
            print(json.dumps(out, indent=2)[:1500])
        elif step == "preview":
            print("\n--- nv_create_registry (preview, no confirm) ---")
            out = call_tool("nv_create_registry", REGISTRY_ARGS)
            print(json.dumps(out, indent=2)[:2000])
            tok = out.get("confirm_token")
            if tok:
                open(os.path.join(HERE, "confirm_token.txt"), "w").write(tok)
                print(f"\nconfirm_token saved: {tok}")
        elif step == "confirm":
            tok = open(os.path.join(HERE, "confirm_token.txt")).read().strip()
            print(f"\n--- nv_create_registry (execute, confirm={tok}) ---")
            out = call_tool("nv_create_registry", {**REGISTRY_ARGS, "confirm": tok})
            print(json.dumps(out, indent=2)[:2000])
        elif step == "confirm-tampered":
            tok = open(os.path.join(HERE, "confirm_token.txt")).read().strip()
            tampered = {**REGISTRY_ARGS, "filters": ["library/*:*"], "confirm": tok}
            print(f"\n--- nv_create_registry (token replay against CHANGED args) ---")
            out = call_tool("nv_create_registry", tampered)
            print(json.dumps(out, indent=2)[:1200])
    return 0


REGISTRY_ARGS = {
    "name": "ash4d-harbor",
    "registry_type": "Docker Registry",
    "registry": "https://registry.ash4d.com",
    "filters": ["ash4d-lab/*:*"],
    "rescan_after_db_update": True,
    "scan_layers": False,
}

if __name__ == "__main__":
    raise SystemExit(main())

